int main () {
    string input;
    getline(cin, input);
    int tagNum;
    cin >> tagNum;
    vector<int> ans(tagNum);
    for (int i = 0; i < tagNum; i++) {
        cin >> ans[i];
    }
    // 记录每个tag的长度和偏移量
    map<int, vector<int>> tagMap;
​
    for (int i = 0; i + 3 < input.size(); i++) {
        int tag = stoi(input.substr(i, 2), nullptr, 16);
        int len = stoi(input.substr(i + 2, 2), nullptr, 16);
        int valueOffset = (i + 5) / 2;

        // 本TLV格式报文段结束位置i
        i += 3 + len * 2;
​
        // i越界说明TLV报文段不完整，丢弃
        if (i >= input.size()) {
            break;
        }
        tagMap[tag] = {len, valueOffset};
    }
​
    for (int tag : ans) {
        if (tagMap.find(tag) != tagMap.end()) {
            vector<int> tmp = tagMap[tag];
            int len  = tmp[0];
            int valueOffset = tmp[1];
            cout << len << " " << valueOffset <<endl;
        // 不存在或丢失    
        } else {
            cout << "0 0" <<endl;
        }
    }
    return 0;
}

