        String input = sc.nextLine();  // 读取十六进制字符串
        int tagNum = sc.nextInt();     // 读取查询的tag数量
        int[] queryTags = new int[tagNum];
        for (int i = 0; i < tagNum; i++) {
            queryTags[i] = sc.nextInt();
        }
​
