        Map<Integer, int[]> tagMap = new HashMap<>();
        for (int i = 0; i + 3 < input.length(); ) {
            int tag = Integer.parseInt(input.substring(i, i + 2), 16);
            int len = Integer.parseInt(input.substring(i + 2, i + 4), 16);
            int valueOffset = (i + 4) / 2;
​
            int nextPos = i + 4 + len * 2;
            // 检查是否越界（TLV不完整）
            if (nextPos > input.length()) {
                break;
            }
            tagMap.put(tag, new int[]{len, valueOffset});
            i = nextPos;
        }
​
        for (int tag : queryTags) {
            if (tagMap.containsKey(tag)) {
                int[] info = tagMap.get(tag);
                System.out.println(info[0] + " " + info[1]);
            } else {
                System.out.println("0 0");
            }
        }
    }
