const readline = require('readline');
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
let inputLines = [];
rl.on('line', line => {
    inputLines.push(line.trim());
}).on('close', () => {
    // 读取十六进制消息字符串
    const input = inputLines[0];
    // 读取tag数量和tag列表
    const tagNum = parseInt(inputLines[1]);
    const queryTags = inputLines.slice(2).map(Number);
​
    // 存储每个tag对应的length和value偏移
    const tagMap = new Map();
​
    let i = 0;
    while (i + 3 < input.length) {
        // 提取tag和length
        const tag = parseInt(input.substring(i, i + 2), 16);
        const len = parseInt(input.substring(i + 2, i + 4), 16);
        const valueOffset = Math.floor((i + 4) / 2);  // 计算value偏移量
​
        const nextPos = i + 4 + len * 2;
        if (nextPos > input.length) break;  // 不完整TLV，丢弃
​
        // 记录tag信息
        tagMap.set(tag, [len, valueOffset]);
        i = nextPos;  // 移动到下一个TLV段
    }
​
    // 输出查询结果
    for (let tag of queryTags) {
        if (tagMap.has(tag)) {
            const [len, offset] = tagMap.get(tag);
            console.log(`${len} ${offset}`);
        } else {
            console.log('0 0');
        }
    }
});
