package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
)
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
​
    // 读取十六进制字符串
    scanner.Scan()
    input := scanner.Text()
​
    // 读取查询tag数量
    scanner.Scan()
    tagNum, _ := strconv.Atoi(scanner.Text())
​
    // 读取查询tag列表
    queryTags := make([]int, tagNum)
    for i := 0; i < tagNum; i++ {
        scanner.Scan()
        queryTags[i], _ = strconv.Atoi(scanner.Text())
    }
​
    // 保存每个tag的长度和value偏移量
    tagMap := make(map[int][2]int)
​
    for i := 0; i+3 < len(input); {
        // 解析tag和length
        tag, _ := strconv.ParseInt(input[i:i+2], 16, 0)
        length, _ := strconv.ParseInt(input[i+2:i+4], 16, 0)
        valueOffset := (i + 4) / 2 // value偏移量（字节）
​
        nextPos := i + 4 + int(length)*2
        // 不完整TLV段，跳出
        if nextPos > len(input) {
            break
        }
​
        // 记录tag的长度和偏移
        tagMap[int(tag)] = [2]int{int(length), valueOffset}
        i = nextPos // 进入下一段TLV
    }
​
    // 输出每个查询tag的结果
    for _, tag := range queryTags {
        if val, ok := tagMap[tag]; ok {
            fmt.Printf("%d %d\n", val[0], val[1])
        } else {
            fmt.Println("0 0")
        }
    }
}
